package com.opensocket.aievent.database.persistence.issueprojection;
import java.time.OffsetDateTime; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.integration.issue.projection.*; import com.opensocket.aievent.database.persistence.issueprojection.dao.IssueRelayDao; import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;
@DatabaseRepositoryAdapter @ConditionalOnProperty(prefix="issue-projection",name="store",havingValue="MYBATIS")
public class MybatisIssueRelayRepository implements IssueRelayRepository {
 private final IssueRelayDao dao; private final IssueProjectionPersistenceConverter c; public MybatisIssueRelayRepository(IssueRelayDao dao,IssueProjectionPersistenceConverter c){this.dao=dao;this.c=c;}
 public CrossProjectIssueRelay saveRelay(CrossProjectIssueRelay v){var old=dao.findRelay(v.tenantId(),v.relayId());if(old==null)dao.insertRelay(c.toPo(v));else if(dao.updateRelayState(c.toPo(v))!=1)throw new IllegalStateException("RESOURCE_VERSION_CONFLICT: issue relay");return findRelay(v.tenantId(),v.relayId()).orElse(v);} public Optional<CrossProjectIssueRelay> findRelay(String t,String id){return Optional.ofNullable(dao.findRelay(t,id)).map(c::relay);} public Optional<CrossProjectIssueRelay> findRelayByIdempotencyKey(String t,String key){return Optional.ofNullable(dao.findRelayByIdempotencyKey(t,key)).map(c::relay);} public List<CrossProjectIssueRelay> listRelays(String t,String task,int n){return dao.listRelays(t,task,n).stream().map(c::relay).toList();} public List<CrossProjectIssueRelay> listDueRelays(OffsetDateTime now,int n){return dao.listDueRelays(now,n).stream().map(c::relay).toList();}
 public IssueRelayAttempt saveRelayAttempt(IssueRelayAttempt v){dao.insertRelayAttempt(c.toPo(v));return v;} public List<IssueRelayAttempt> listRelayAttempts(String t,String relay,int n){return dao.listRelayAttempts(t,relay,n).stream().map(c::attempt).toList();} public String mode(){return "MYBATIS";}
}
